{"explanation":"The matrix sends each point (x, y) to (2x + y, y): it stretches horizontally and adds a shear, while leaving height unchanged. The unit square becomes a parallelogram with area 2, illustrating that det(A) = 2 is the area multiplier for every region in the plane. Move the slider to watch the transformation unfold; the positive determinant means orientation is preserved.","manimCode":"const title = new Text({ text: 'How a matrix reshapes the plane', fontSize: 30, color: WHITE });
title.moveTo([0, 3.3, 0]);
const formula = new MathTex({ latex: 'A=\\begin{pmatrix}2&1\\\\0&1\\end{pmatrix},\\qquad (x,y)\\mapsto(2x+y,y)' });
await formula.waitForRender();
formula.scale(0.75).moveTo([0, 2.6, 0]);
scene.add(title, formula);

const ax = new Axes({ xRange: [-4, 4, 1], yRange: [-2.3, 2.3, 1], xLength: 8, yLength: 4.6, tips: false });
ax.moveTo([-1, -0.35, 0]);
scene.add(ax);

const progress = new ValueTracker(0);
function mappedPoint(x, y) {
  const amount = progress.getValue();
  return ax.coordsToPoint((1 + amount) * x + amount * y, y);
}

const gridSegments = [];
function addGridSegment(first, second) {
  const segment = new Polygon({ vertices: [mappedPoint(...first), mappedPoint(...second)], color: BLUE_E });
  segment.setFillOpacity(0);
  segment.setStrokeWidth(1);
  gridSegments.push({ segment, first, second });
  scene.add(segment);
}
for (let k = -3; k <= 3; k++) {
  const x = k / 2;
  addGridSegment([x, -1], [x, 1]);
}
for (let k = -2; k <= 2; k++) {
  const y = k / 2;
  addGridSegment([-1.5, y], [1.5, y]);
}

const corners = [[0, 0], [1, 0], [1, 1], [0, 1]];
const originalSquare = new Polygon({ vertices: corners.map(([x, y]) => ax.coordsToPoint(x, y)), color: GRAY });
originalSquare.setFill(GRAY, 0.08);
originalSquare.setStrokeWidth(2);
const movingSquare = new Polygon({ vertices: corners.map(([x, y]) => mappedPoint(x, y)), color: GOLD });
movingSquare.setFill(GOLD, 0.3);
movingSquare.setStrokeWidth(3);

const firstVector = new Polygon({ vertices: [mappedPoint(0, 0), mappedPoint(1, 0)], color: BLUE });
const secondVector = new Polygon({ vertices: [mappedPoint(0, 0), mappedPoint(0, 1)], color: ORANGE });
firstVector.setFillOpacity(0);
secondVector.setFillOpacity(0);
firstVector.setStrokeWidth(5);
secondVector.setStrokeWidth(5);
const firstTip = new Dot({ point: mappedPoint(1, 0), color: BLUE });
const secondTip = new Dot({ point: mappedPoint(0, 1), color: ORANGE });
scene.add(originalSquare, movingSquare, firstVector, secondVector, firstTip, secondTip);

movingSquare.addUpdater(() => {
  movingSquare.setVertices(corners.map(([x, y]) => mappedPoint(x, y)));
  for (const entry of gridSegments) {
    entry.segment.setVertices([mappedPoint(...entry.first), mappedPoint(...entry.second)]);
  }
  firstVector.setVertices([mappedPoint(0, 0), mappedPoint(1, 0)]);
  secondVector.setVertices([mappedPoint(0, 0), mappedPoint(0, 1)]);
  firstTip.moveTo(mappedPoint(1, 0));
  secondTip.moveTo(mappedPoint(0, 1));
});

const determinant = new MathTex({ latex: '\\det A=2\\cdot1-1\\cdot0=2' });
await determinant.waitForRender();
determinant.scale(0.6).moveTo([4.5, 1.5, 0]);
const originalArea = new Text({ text: 'Original area: 1', fontSize: 21, color: GRAY });
originalArea.moveTo([4.5, 0.85, 0]);
scene.add(determinant, originalArea);

const firstCaption = new Text({ text: '(1, 0) becomes (2, 0)', fontSize: 21, color: BLUE });
firstCaption.moveTo([-2.5, -3.05, 0]);
const secondCaption = new Text({ text: '(0, 1) becomes (1, 1)', fontSize: 21, color: ORANGE });
secondCaption.moveTo([2.1, -3.05, 0]);
scene.add(firstCaption, secondCaption);

await scene.wait(0.6);
await scene.play(progress.animateTo(1));

let areaLabel;
function refreshAreaLabel() {
  if (areaLabel) scene.remove(areaLabel);
  areaLabel = new Text({ text: 'Current area: ' + (1 + progress.getValue()).toFixed(2), fontSize: 21, color: GOLD });
  areaLabel.moveTo([4.5, 0.25, 0]);
  scene.add(areaLabel);
}
refreshAreaLabel();
makeHoverable(movingSquare, scene, { hoverScale: 1, hoverOpacity: 0.55 });

const controls = new Controls(scene, { position: 'bottom-right', width: 260 });
controls.addSlider({ label: 'Transformation progress', min: 0, max: 1, value: 1, step: 0.01, onChange: (value) => {
  progress.setValue(value);
  refreshAreaLabel();
} });

await scene.wait(999999);"}

